export function evaluate(merged, tool, args) {
  for (const rule of merged) if (matchRule(rule, tool, args)) return rule
  return undefined
}

// 引擎需要的便捷封装：合并作用域并求值
export function evaluateScopes(scopes, tool, args) {
  return evaluate(mergeRules(scopes), tool, args)
}
```

