// ---------- 路径匹配 ----------
export function normPath(p) {
  let s = String(p).trim()
  if (s === '') return s
  s = s.replace(/\\/g, '/')
  while (s.includes('//')) s = s.replace(/\/\//g, '/')
  if (s.length > 1 && s.endsWith('/')) s = s.slice(0, -1)
  return s.toLowerCase()
}

