    {
      "path": "lib/index.js",
      "content": "import { appendFile, readFile, writeFile, mkdir, rename, copyFile, stat } from 'node:fs/promises'\nimport { homedir } from 'node:os'\nimport path from 'node:path'\nimport { ACTIONS, FILE_TOOLS, EMPTY, compileRule, mergeRules, primaryArgOf, normPath, matchPathPattern, candidateArgs, matchRule, evaluate } from './match.js'\n\nexport const name = 'permissions-engine'\nexport const inject = ['webServer']\n\nconst DEFAULT_HARD = [\n  'write(.ssh)', 'edit(.ssh)', 'write(.aws)', 'edit(.aws)',\n  'write(.gnupg)', 'edit(.gnupg)', 'write(appdata)', 'edit(appdata)',\n  'write(*.pem)', 'edit(*.pem)', 'write(*.key)', 'edit(*.key)',\n  'write(*.env)', 'edit(*.env)', 'write(*.htpasswd)', 'edit(*.htpasswd)',\n]\nconst DEFAULT_DENY = ['pwsh(rm -rf *)']\nconst DEFAULT_ASK = ['pwsh', 'edit', 'write']\nconst DEFAULT_ALLOW = ['read', 'glob', 'grep', 'web_search']\n\n// ---------- 规则编译/合并（前缀语义 + 通配符） ----------\nfunction sourceLabel(source) {\n  return source === 'global' ? 'global' : source.slice(0, 3) === 'ws:' ? 'workspace ' + source.slice(3) : source\n}\n\n// ---------- 模型可见的规则摘要（systemPrompt 段） ----------\nfunction summaryText(current) {\n  if (!current || !current.enabled) return ''\n  const parts = []\n  const push = (label, list) => {\n    if (!list || list.length === 0) return\n    parts.push(label + ': ' + list.slice(0, 8).join('; ') + (list.length > 8 ? '; …' : ''))\n  }\n  push('Hard', current.hard)\n  push('Deny', current.deny)\n  push('Ask', current.ask)\n  push('Allow', current.allow)\n  const ws = current.workspaces || {}\n  for (const id of Object.keys(ws).slice(0, 3)) {\n    const w = ws[id] || EMPTY\n    push('Hard(ws:' + id + ')', w.hard)\n    push('Deny(ws:' + id + ')', w.deny)\n    push('Allow(ws:' + id + ')', w.allow)\n  }\n  if (parts.length === 0) return ''\n  return '[active-permission-rules]\\n' + parts.join('\\n') + '\\n优先级: hard > deny > ask > allow；hard 高于 full access，被拒的调用请勿重试。'\n}\n\n// 校验 POST /api/dperm/rules 的请求体。返回错误描述字符串，合法时返回 undefined。\n// 旧实现只检查\"是个对象\"：传 {\"hard\":\"abc\"} 会被原样存盘，之后 mergeRules 去遍历字符串\n// 的每个字符，静默产出零可用规则。\nfunction validateSection(section) {\n  if (section === null || typeof section !== 'object' || Array.isArray(section)) return 'body must be a JSON object'\n  if (section.enabled !== undefined && typeof section.enabled !== 'boolean') return 'enabled must be a boolean'\n  const ruleKeys = ['hard', 'deny', 'ask', 'allow']\n  for (const k of ruleKeys) {\n    const v = section[k]\n    if (v === undefined) continue\n    if (!Array.isArray(v) || v.some((x) => typeof x !== 'string')) return k + ' must be an array of strings'\n  }\n  const ws = section.workspaces\n  if (ws !== undefined) {\n    if (ws === null || typeof ws !== 'object' || Array.isArray(ws)) return 'workspaces must be an object'\n    for (const id of Object.keys(ws)) {\n      const set = ws[id]\n      if (set === null || typeof set !== 'object' || Array.isArray(set)) return 'workspaces.' + id + ' must be an object'\n      for (const k of ruleKeys) {\n        const v = set[k]\n        if (v === undefined) continue\n        if (!Array.isArray(v) || v.some((x) => typeof x !== 'string')) return 'workspaces.' + id + '.' + k + ' must be an array of strings'\n      }\n    }\n  }\n  return undefined\n}\n\nexport function apply(ctx) {\n  // ---------- 自管 JSON 持久化（替代 settings 命名空间，兼容 0.1.7 的 settings 重构） ----------\n  // dsh ≥ 0.1.7-alpha.1 移除了 ctx.settings.register（SettingsForms 重构）；\n  // 改为自管 JSON 文件，读写路径与旧 settings.yaml 中的规则互不冲突。\n  // 迁移：首次运行时若 settings.yaml 有 dsh-permissions 段则一次性导入。\n  const dshHome = process.env.DSH_HOME || path.join(homedir(), '.dsh')\n  const stateFile = path.join(dshHome, 'dsh-permissions-state.json')\n  const defaultState = () => ({\n    enabled: true,\n    hard: DEFAULT_HARD.slice(),\n    deny: DEFAULT_DENY.slice(),\n    ask: DEFAULT_ASK.slice(),\n    allow: DEFAULT_ALLOW.slice(),\n    workspaces: {},\n  })\n  let current = defaultState()\n  let stateLoaded = false\n  const loadState = async () => {\n    if (stateLoaded) return\n    stateLoaded = true\n    try {\n      const text = await readFile(stateFile, 'utf8')\n      const parsed = JSON.parse(text)\n      if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {\n        // 合并到默认值之上：旧版/残缺文件缺少的字段自动补默认，而不是变成 undefined\n        current = Object.assign(defaultState(), parsed)\n      }\n    } catch (e) {\n      // 首次运行：尝试从旧 settings.yaml 迁移\n      try {\n        const yamlPath = path.join(dshHome, 'settings.yaml')\n        const yaml = await readFile(yamlPath, 'utf8')\n        const m = yaml.match(/dsh-permissions:\\n((?:[ \\t]+.*\\n?)*)/)\n        if (m) {\n          // 极简 YAML 解析（只处理我们自己的扁平结构）\n          const section = m[1]\n          const parseList = (key) => {\n            const km = section.match(new RegExp('[ \\\\t]+' + key + ':(?:\\\\n[ \\\\t]+- ([^\\\\n]*))+'))\n            if (!km) return undefined\n            return km[0].split('\\n').filter((l) => l.trim().startsWith('- ')).map((l) => l.trim().slice(2).trim())\n          }\n          const en = section.match(/[ \\t]+enabled: (\\S+)/)\n          const migrated = {}\n          if (en) migrated.enabled = en[1] === 'true'\n          for (const k of ['hard', 'deny', 'ask', 'allow']) {\n            const list = parseList(k)\n            if (list !== undefined) migrated[k] = list\n          }\n          if (Object.keys(migrated).length > 0) {\n            current = Object.assign({}, current, migrated)\n            await mkdir(path.dirname(stateFile), { recursive: true })\n            await writeFile(stateFile, JSON.stringify(current, null, 2) + '\\n', 'utf8')\n          }\n        }\n      } catch (e2) { /* 无旧配置 */ }\n    }\n  }\n  // 缓存与修订号声明在 saveState 之前（loadState 的异步回调可能在声明之后才执行，\n  // 但安全起见把声明放最前，避免 TDZ 问题）\n  let rulesRev = 0\n  const wsCache = new Map()\n  const mergedCache = new Map()\n  const saveState = async (next) => {\n    current = next\n    rulesRev += 1\n    wsCache.clear()\n    mergedCache.clear()\n    try {\n      await mkdir(path.dirname(stateFile), { recursive: true })\n      // 原子写：先写 .tmp，把旧文件备份为 .bak，再 rename 覆盖（同卷 rename 是原子替换）。\n      // 避免写到一半崩溃留下截断 JSON → 下次启动被当成\"首次运行\"静默丢光规则。\n      const tmp = stateFile + '.tmp'\n      await writeFile(tmp, JSON.stringify(current, null, 2) + '\\n', 'utf8')\n      try { await copyFile(stateFile, stateFile + '.bak') } catch (e) { /* 首次保存无旧文件 */ }\n      await rename(tmp, stateFile)\n    } catch (e) { /* 写失败不阻塞 */ }\n  }\n  loadState()\n\n  const workspaceRegistry = ctx.get('workspaceRegistry')\n  const approval = ctx.get('approval')\n  const systemPrompt = ctx.get('systemPrompt')\n\n  // ---------- 会话授予（\"本会话总是允许\"） ----------\n  // grants: sessionId -> Set<ruleKey>；pending: callId -> {resolve, tool, arg, rule, agent}\n  const grants = new Map()\n  const pendingAsks = new Map()\n  const ASK_PREFIX = '[dsh-permissions-ask] '\n  function grantKeyOf(rule) {\n    return rule.source + '|' + rule.action + '|' + rule.raw\n  }\n  function hasGrant(agent, rule) {\n    const sid = agent && agent.session ? String(agent.session.id) : ''\n    const set = grants.get(sid)\n    return set !== undefined && set.has(grantKeyOf(rule))\n  }\n  function addGrant(agent, rule) {\n    const sid = agent && agent.session ? String(agent.session.id) : ''\n    if (sid === '') return\n    let set = grants.get(sid)\n    if (set === undefined) { set = new Set(); grants.set(sid, set) }\n    set.add(grantKeyOf(rule))\n  }\n  function grantsOfSession(sid) {\n    const set = grants.get(sid)\n    if (set === undefined) return []\n    return [...set].map((key) => {\n      const sep1 = key.indexOf('|')\n      const sep2 = key.indexOf('|', sep1 + 1)\n      return { source: key.slice(0, sep1), action: key.slice(sep1 + 1, sep2), raw: key.slice(sep2 + 1) }\n    })\n  }\n\n  // 抢答器：拦截自家 ask 问询（reason 带 ASK_PREFIX），改走 /api/dperm/ask 的三选 UI\n  if (approval !== undefined) {\n    ctx.on('approval/request', (req, next) => {\n      if (req.signal && req.signal.aborted) return next(